import { LibSQLVector } from '@mastra/libsql'
import { prepareChunks } from './documents.js'
import { embedTexts, embeddingModel } from './embedding.js'

// 每个入口独立建立内存索引；真实入库与检索使用同一种 Embedding 配置。
export async function createIndex () {
  const chunks = await prepareChunks()
  const vectors = await embedTexts(chunks.map(chunk => chunk.text))
  const store = new LibSQLVector({ id: 'travel-vectors', url: ':memory:' })
  const indexName = 'travel_policy'
  try {
    await store.createIndex({ indexName, dimension: vectors[0].length })
    await store.upsert({ indexName, ids: chunks.map(c => c.id), vectors, metadata: chunks.map(c => ({ ...c.metadata, embeddingModel })) })
    return { store, indexName, chunks, vectors }
  } catch (error) { await store.close(); throw error }
}

// 团队范围来自调用侧已确认的身份，检索时同时排除失效制度。
export async function retrieve (index, question, teamId) {
  const [queryVector] = await embedTexts([question])
  return index.store.query({ indexName: index.indexName, queryVector, topK: 4, filter: { teamId, active: true } })
}

import { createIndex } from './index.js'
import { embeddingModel } from './embedding.js'

// 核对真实索引状态，并删除已失效制度的一个片段。
const index = await createIndex()
try {
  const before = await index.store.describeIndex({ indexName: index.indexName })
  const chunk = index.chunks[0]
  await index.store.upsert({ indexName: index.indexName, ids: [chunk.id], vectors: [index.vectors[0]], metadata: [{ ...chunk.metadata, embeddingModel }] })
  const repeated = await index.store.describeIndex({ indexName: index.indexName })
  console.log('同一片段 id 再写入后的数量：', repeated.count)
  await index.store.deleteVector({ indexName: index.indexName, id: chunk.id })
  const after = await index.store.describeIndex({ indexName: index.indexName })
  console.log('入库片段数：', index.chunks.length, '索引状态：', before)
  console.log('删除一个旧版片段后：', after)
} finally { await index.store.close() }

